 const string Root="Assets/ROM/Combat";static readonly List<string> report=new List<string>();static readonly Dictionary<Material,Material> materials=new Dictionary<Material,Material>();
 static T Asset<T>(string name)where T:ScriptableObject{string p=Root+"/"+name+".asset";var a=AssetDatabase.LoadAssetAtPath<T>(p);if(!a){a=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(a,p);}return a;}
 static AnimationClip Clip(string filename){string path=AssetDatabase.FindAssets(filename+" t:Model",new[]{"Assets/Raise Creation/Samurai Animation Pack/Animations"}).Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>Path.GetFileNameWithoutExtension(p)==filename);if(path==null)throw new Exception("Missing animation "+filename);var clip=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__"));if(!clip.isHumanMotion)throw new Exception("Not humanoid: "+path);return clip;}
 static Material Convert(Material original){if(!original)return null;if(materials.TryGetValue(original,out var known))return known;string p=Root+"/Materials/"+original.name+"-"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(original)).Substring(0,8)+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(p);if(original.shader.name.StartsWith("Shader Graphs/HS_")){if(!mat){mat=new Material(original);AssetDatabase.CreateAsset(mat,p);}else{mat.shader=original.shader;mat.CopyPropertiesFromMaterial(original);}EditorUtility.SetDirty(mat);materials[original]=mat;report.Add("Hovl URP graph preserved: "+original.shader.name+" supported="+original.shader.isSupported);return mat;}if(!mat){bool particle=original.shader.name.Contains("Particle")||original.shader.name.Contains("VFX")||original.shader.name.Contains("Hovl");mat=new Material(Shader.Find(particle?"Universal Render Pipeline/Particles/Unlit":"Universal Render Pipeline/Lit"));mat.name=original.name+" ROM URP";Texture tex=original.HasProperty("_BaseMap")?original.GetTexture("_BaseMap"):original.HasProperty("_MainTex")?original.GetTexture("_MainTex"):null;mat.SetTexture("_BaseMap",tex);Color color=original.HasProperty("_BaseColor")?original.GetColor("_BaseColor"):original.HasProperty("_MainColor")?original.GetColor("_MainColor"):original.HasProperty("_TintColor")?original.GetColor("_TintColor"):original.HasProperty("_Color")?original.GetColor("_Color"):Color.white;mat.SetColor("_BaseColor",color);if(particle){mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetFloat("_SrcBlend",5);mat.SetFloat("_DstBlend",10);mat.SetFloat("_ZWrite",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.renderQueue=3000;mat.SetFloat("_Cull",0);}else{if(original.HasProperty("_BumpMap")){mat.SetTexture("_BumpMap",original.GetTexture("_BumpMap"));mat.EnableKeyword("_NORMALMAP");}if(original.HasProperty("_MetallicGlossMap")){mat.SetTexture("_MetallicGlossMap",original.GetTexture("_MetallicGlossMap"));mat.EnableKeyword("_METALLICSPECGLOSSMAP");}}AssetDatabase.CreateAsset(mat,p);}materials[original]=mat;report.Add("Material: "+original.shader.name+" => "+mat.shader.name+" supported="+mat.shader.isSupported);return mat;}
 static GameObject Wrapper(string source,string name,bool persistent=false){string path=Root+"/Prefabs/"+name+".prefab";var original=AssetDatabase.LoadAssetAtPath<GameObject>(source);if(!original)throw new Exception("Missing asset "+source);var go=UnityEngine.Object.Instantiate(original);go.name=name;foreach(var script in go.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);foreach(var light in go.GetComponentsInChildren<Light>(true))UnityEngine.Object.DestroyImmediate(light);foreach(var c in go.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var r in go.GetComponentsInChildren<Renderer>(true))r.sharedMaterials=r.sharedMaterials.Select(Convert).ToArray();int count=0;int budget=Mathf.Max(4,256/Mathf.Max(1,go.GetComponentsInChildren<ParticleSystem>(true).Length));foreach(var ps in go.GetComponentsInChildren<ParticleSystem>(true)){var m=ps.main;m.maxParticles=Mathf.Min(m.maxParticles,Mathf.Min(32,budget));m.stopAction=ParticleSystemStopAction.None;m.loop=persistent;var collision=ps.collision;collision.enabled=false;var lights=ps.lights;lights.enabled=false;count+=m.maxParticles;}var prefab=PrefabUtility.SaveAsPrefabAsset(go,path);report.Add(name+": source="+source+" particles capped total="+count);UnityEngine.Object.DestroyImmediate(go);return prefab;}
 static WeaponDefinition Weapon(string id,string source,float length){var w=Asset<WeaponDefinition>(id);w.Id=id;w.DisplayName=id;w.WeaponType=id=="GuardianSword"?"OneHandSword":"TwoHandSword";w.Model=Wrapper(source,id);var renderers=w.Model.GetComponentsInChildren<Renderer>();var b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);float largest=Mathf.Max(b.size.x,b.size.y,b.size.z);w.Scale=Vector3.one*length/Mathf.Max(.01f,largest);w.Rotation=new Vector3(0,0,90);w.Position=Vector3.zero;w.Reach=3.5f;w.AllowedClasses=new[]{"warrior"};w.AllowedSpecializations=new[]{id=="GuardianSword"?"guardian":"ravager"};w.Attack=Clip("Anim_Samurai_Attack_Strike");EditorUtility.SetDirty(w);report.Add(id+" original bounds="+b+" scale="+w.Scale);return w;}
 static AbilityDefinition Ability(string id,string name,AbilityShape shape,float damage,float radius,float cooldown,float cost,float gain,string clip,GameObject effect){var a=Asset<AbilityDefinition>(id);a.Id=id;a.DisplayName=name;a.Shape=shape;a.Damage=damage;a.Radius=a.Range=radius;a.Cooldown=cooldown;a.Cost=cost;a.ResourceGain=gain;a.Animation=Clip(clip);a.ImpactVfx=effect;a.HitTime=.3f;a.CastDuration=.75f;a.Recovery=.2f;a.Implemented=true;EditorUtility.SetDirty(a);return a;}
 [MenuItem("ROM/Combate/Construir prototipo Nertör")]
 public static void Build(){
  Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Prefabs");Directory.CreateDirectory("Documentation/combat-slice");AssetDatabase.Refresh();report.Clear();
  var hit=Wrapper("Assets/Hovl Studio/RPG VFX Bundle/Random effect prefabs/Punch Hit.prefab","MeleeImpact");
  var slam=Wrapper("Assets/Hovl Studio/RPG VFX Bundle/Random effect prefabs/Chain explosion.prefab","EarthbreakerImpact");
  var roar=Wrapper("Assets/Hovl Studio/RPG VFX Bundle/Random effect prefabs/Buff palladin.prefab","WarbornBuff");
  var crack=Wrapper("Assets/SpaceCrackTeleport/Prefabs/SpaceCrackTeleport_BuiltIn/Effect2.prefab","DimensionalPortal",true);
  var sword=Weapon("GuardianSword","Assets/Free medieval weapons/Prefabs/Sword_OH.prefab",1.15f);var heavy=Weapon("RavagerSword","Assets/Free medieval weapons/Prefabs/Sword_DH.prefab",1.55f);
  var basic=Ability("BasicAttack","Ataque",AbilityShape.Arc,22,3.4f,.85f,0,12,"Anim_Samurai_Attack_Strike",hit);basic.Arc=90;
  var cleave=Ability("CleavingFury","Furia cortante",AbilityShape.Arc,38,4.5f,4,0,18,"Anim_Samurai_Attack_Round",hit);cleave.Arc=150;
  var earth=Ability("Earthbreaker","Rompetierra",AbilityShape.Circle,65,6,9,25,0,"Anim_Samurai_Attack_Strike_Perfect",slam);earth.Stagger=.9f;earth.CastDuration=.9f;earth.HitTime=.52f;
  var war=Ability("HonoredRoar","Rugido de honor",AbilityShape.Self,0,10,15,15,0,"Anim_Samurai_Block_Idle",roar);war.BuffDuration=6;war.DamageReduction=.4f;war.OffensiveBonus=.3f;
  var leap=Asset<AbilityDefinition>("WarbornLeap");leap.Id="warborn-leap";leap.DisplayName="Salto de guerra";leap.Implemented=false;
  var whirl=Asset<AbilityDefinition>("WhirlingExecution");whirl.Id="whirling-execution";whirl.DisplayName="Ejecución giratoria";whirl.Implemented=false;
  var stand=Asset<AbilityDefinition>("LastStand");stand.Id="last-stand";stand.DisplayName="Última resistencia";stand.Implemented=false;
  var guardian=Asset<SpecializationDefinition>("Guardian");guardian.Id="guardian";guardian.DisplayName="Guardian";guardian.Health=220;guardian.Armor=.2f;guardian.DamageMultiplier=1;guardian.ThreatMultiplier=3;guardian.Weapon=sword;
  var ravager=Asset<SpecializationDefinition>("Ravager");ravager.Id="ravager";ravager.DisplayName="Ravager";ravager.Health=170;ravager.Armor=.08f;ravager.DamageMultiplier=1.3f;ravager.ThreatMultiplier=1;ravager.Weapon=heavy;
  var warrior=Asset<CombatClassDefinition>("Warrior");warrior.Id="warrior";warrior.DisplayName="Guerrero";warrior.Resource=CombatResourceKind.Rage;warrior.BasicAttack=basic;warrior.Abilities=new[]{cleave,earth,war,leap,whirl,stand};warrior.Specializations=new[]{guardian,ravager};
  var species=Asset<SpeciesDefinition>("Nertor");species.Id="nertor";species.DisplayName="Nertör";species.SkinIndices=new[]{1};species.Classes=new[]{warrior};
  var enemyAttack=Ability("EnemyStrike","Golpe enemigo",AbilityShape.Arc,16,2.8f,3,0,0,"Anim_Samurai_Attack_Strike",hit);
  var casterAttack=Ability("EnemyBolt","Descarga arcana",AbilityShape.Projectile,18,16,4,0,0,"Anim_Samurai_Block_Idle",hit);casterAttack.CastVfx=roar;
  string[] names={"MeleeGrunt","MeleeBruiser","MeleeElite","RangedCaster","CasterElite"};var enemies=new EnemyArchetypeDefinition[5];for(int i=0;i<5;i++){var e=Asset<EnemyArchetypeDefinition>(names[i]);e.Id=names[i];e.DisplayName=names[i];e.Caster=i>=3;e.Attack=e.Caster?casterAttack:enemyAttack;e.Damage=i==2||i==4?25:16;e.Range=e.Caster?16:2.8f;e.Windup=e.Caster?1.2f:.8f;e.Cooldown=e.Caster?3.5f:2.7f;e.MoveSpeed=i==1?2.6f:3.2f;enemies[i]=e;}
  foreach(var a in new ScriptableObject[]{basic,cleave,earth,war,leap,whirl,stand,guardian,ravager,warrior,species,enemyAttack,casterAttack}.Concat(enemies))EditorUtility.SetDirty(a);
  AssetDatabase.SaveAssets();
  string playerPath="Assets/MultiFPS/Levels/Prefabs/Gameplay/MultiFPS_PlayerInstance.prefab";var player=PrefabUtility.LoadPrefabContents(playerPath);var ability=player.GetComponent<AbilityController>();if(!ability)ability=player.AddComponent<AbilityController>();ability.Species=species;PrefabUtility.SaveAsPrefabAsset(player,playerPath);PrefabUtility.UnloadPrefabContents(player);
  foreach(string path in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/MultiFPS/Levels"}).Select(AssetDatabase.GUIDToAssetPath)){var obj=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!obj.GetComponent<CharacterInstance>())continue;var go=PrefabUtility.LoadPrefabContents(path);var ai=go.GetComponent<RiftEnemyCombat>();if(!ai)ai=go.AddComponent<RiftEnemyCombat>();ai.Archetypes=enemies;ai.MeleeWeapon=sword;if(!go.GetComponent<CombatEquipment>())go.AddComponent<CombatEquipment>();PrefabUtility.SaveAsPrefabAsset(go,path);PrefabUtility.UnloadPrefabContents(go);report.Add("Character network prefab patched: "+path);}
  var scene=EditorSceneManager.OpenScene(ProjectSceneCleanup.Rift);var old=GameObject.Find("El Rift - Nertor vertical slice");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("El Rift - Nertor vertical slice");
  Heart(root.transform,crack);Portals(root.transform,crack);
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  string hubPath="Assets/ROM/UI/Sprint01/ROM_RiftHub.prefab";var hubPrefab=PrefabUtility.LoadPrefabContents(hubPath);hubPrefab.GetComponent<ROM.UI.Sprint01.RiftHub>().CombatSpecies=species;PrefabUtility.SaveAsPrefabAsset(hubPrefab,hubPath);PrefabUtility.UnloadPrefabContents(hubPrefab);var menu=EditorSceneManager.OpenScene(ProjectSceneCleanup.Menu);foreach(var hub in UnityEngine.Object.FindObjectsByType<ROM.UI.Sprint01.RiftHub>(FindObjectsInactive.Include,FindObjectsSortMode.None)){hub.CombatSpecies=species;EditorUtility.SetDirty(hub);}EditorSceneManager.SaveScene(menu);
  AssetDatabase.SaveAssets();File.WriteAllLines("Documentation/combat-slice/asset-validation.txt",report);Debug.Log("NERTOR BUILD COMPLETE");
 }
 static Mesh CrystalMesh(){var mesh=new Mesh{name="Fractured crystal"};var vertices=new List<Vector3>();var triangles=new List<int>();Vector3 top=new Vector3(.1f,1.5f,0),bottom=new Vector3(-.15f,-1.2f,0);for(int i=0;i<6;i++){float a=i*Mathf.PI/3,b=(i+1)*Mathf.PI/3;Vector3 v=new Vector3(Mathf.Cos(a),.1f*Mathf.Sin(i*3),Mathf.Sin(a)),w=new Vector3(Mathf.Cos(b),.1f*Mathf.Sin((i+1)*3),Mathf.Sin(b));int k=vertices.Count;vertices.AddRange(new[]{top,w,v,bottom,v,w});triangles.AddRange(new[]{k,k+1,k+2,k+3,k+4,k+5});}mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
 static void Heart(Transform parent,GameObject crack){var root=new GameObject("The Fractured Heart");root.transform.SetParent(parent);root.transform.position=new Vector3(130,330,600);var material=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Heart.mat");if(!material){material=new Material(Shader.Find("ROM/Fractured Heart"));material.SetColor("_BaseColor",new Color(.3f,.035f,1.2f));AssetDatabase.CreateAsset(material,Root+"/Materials/Heart.mat");}var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/HeartCrystal.asset");if(!mesh){mesh=CrystalMesh();AssetDatabase.CreateAsset(mesh,Root+"/HeartCrystal.asset");}Transform Piece(string name,Vector3 pos,Vector3 scale,Transform owner){var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(owner,false);go.transform.localPosition=pos;go.transform.localScale=scale;go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=material;go.GetComponent<MeshRenderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;return go.transform;}
  var heart=root.AddComponent<FracturedHeart>();heart.Crystal=Piece("Giant suspended crystal",Vector3.zero,new Vector3(23,39,23),root.transform);heart.Fragments=new GameObject("Orbiting fragments").transform;heart.Fragments.SetParent(root.transform,false);for(int i=0;i<11;i++){float a=i*2.39996f;Piece("Fragment "+i,new Vector3(Mathf.Cos(a)*(48+i*2),Mathf.Sin(a*1.4f)*47,Mathf.Sin(a)*(35+i*2)),Vector3.one*(4+i%4),heart.Fragments);}
  for(int j=0;j<3;j++){var go=new GameObject("Dimensional fracture "+j,typeof(LineRenderer));go.transform.SetParent(root.transform,false);var line=go.GetComponent<LineRenderer>();line.useWorldSpace=false;line.sharedMaterial=material;line.widthMultiplier=j==0?1.2f:.6f;line.positionCount=97;for(int i=0;i<=96;i++){float a=i*Mathf.PI*2/96;float r=76+j*9+Mathf.Sin(i*1.7f+j)*.7f;line.SetPosition(i,new Vector3(Mathf.Cos(a)*r,Mathf.Sin(a)*r,Mathf.Sin(a*3+j)*8));}}
  var glow=(GameObject)PrefabUtility.InstantiatePrefab(crack);glow.name="Heart dimensional energy";glow.transform.SetParent(root.transform,false);glow.transform.localScale=Vector3.one*15;
  var atmosphere=UnityEngine.Object.FindFirstObjectByType<RiftNightAtmosphere>();if(atmosphere&&atmosphere.Moon){heart.WorldLight=atmosphere.Moon;heart.WorldLight.transform.rotation=Quaternion.LookRotation(-root.transform.position.normalized);atmosphere.MoonColor=heart.Calm;atmosphere.MoonIntensity=heart.BaseLight;atmosphere.Apply();}
 }
 static void Portals(Transform parent,GameObject effect){var start=UnityEngine.Object.FindObjectsByType<RiftCheckpoint>(FindObjectsSortMode.None).First(c=>c.StartingCamp);var west=UnityEngine.Object.FindObjectsByType<RiftCheckpoint>(FindObjectsSortMode.None).OrderBy(c=>Vector3.Distance(c.transform.position,new Vector3(-310,8,0))).First();
  Vector3 a=start.transform.position+new Vector3(26,0,18),b=west.transform.position+new Vector3(6,0,4);var portals=new RiftPortal[2];for(int i=0;i<2;i++){var definition=Asset<PortalDefinition>("Portal"+i);definition.Id=i;definition.DisplayName=i==0?"Viajar a las ruinas":"Volver al refugio";definition.Effect=effect;EditorUtility.SetDirty(definition);var go=new GameObject(definition.DisplayName);go.transform.SetParent(parent);Vector3 point=i==0?a:b;if(UnityEngine.AI.NavMesh.SamplePosition(point,out var hit,12,UnityEngine.AI.NavMesh.AllAreas))point=hit.position;go.transform.position=point;var portal=go.AddComponent<RiftPortal>();portal.Definition=definition;var visual=(GameObject)PrefabUtility.InstantiatePrefab(effect);visual.transform.SetParent(go.transform,false);visual.transform.localScale=Vector3.one*1.5f;portals[i]=portal;}
  for(int i=0;i<2;i++){var arrival=new GameObject("Arrival safe").transform;arrival.SetParent(portals[1-i].transform,false);arrival.localPosition=new Vector3(0,.15f,-5);portals[i].Destination=arrival;report.Add("Portal "+i+" "+portals[i].transform.position+" => "+arrival.position);}
 }
 public static void Run(){try{Build();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
